 TextBlock gameLocation,bepState; readonly StackPanel platformSwitch=new StackPanel();
 void BuildSwitch(){platformSwitch.Children.Clear();foreach(string source in installer.AvailablePlatforms){var b=MakeButton(false,8);b.Content=Text(source,12,true);b.Width=66;b.Height=30;b.Margin=new Thickness(5,0,0,0);b.Tag=source;b.Click+=(s,e)=>{installer.SelectPlatform(source);UpdateLocation();};platformSwitch.Children.Add(b);}}
 TextBlock Text(string value,double size,bool bold){return new TextBlock{Text=value,FontSize=size,FontWeight=bold?FontWeights.SemiBold:FontWeights.Normal,Foreground=ink,VerticalAlignment=VerticalAlignment.Center};}
 void UpdateLocation(){gameLocation.Text=string.IsNullOrEmpty(installer.GamePath)?"Steam / Meta · sélectionner au premier clic":installer.GamePath;gameLocation.ToolTip=gameLocation.Text;foreach(Button b in platformSwitch.Children){bool selected=(string)b.Tag==installer.SelectedPlatform;b.Content=Text((selected?"● ":"")+(string)b.Tag,12,true);((TextBlock)b.Content).Foreground=selected?new SolidColorBrush(Color.FromRgb(105,167,255)):ink;}if(bepState!=null){string state=string.IsNullOrEmpty(installer.GamePath)?"Jeu non détecté":ModInstaller.CheckBepInEx(installer.GamePath);bepState.Text="●  "+state;bepState.Foreground=new SolidColorBrush(state=="Installé"?Color.FromRgb(68,192,140):Color.FromRgb(233,166,76));bepState.ToolTip="Vérification des fichiers BepInEx de cette installation.";}}
 Button ChromeButton(string label,Action action){var b=MakeButton(false,12);b.Width=30;b.Height=28;b.Margin=new Thickness(5,0,0,0);b.Content=new TextBlock{Text=label,FontSize=20,Foreground=ink,HorizontalAlignment=HorizontalAlignment.Center};b.Click+=(s,e)=>action();return b;}
 Button ActionButton(string text,string geometry,bool primary,Action action){var b=MakeButton(primary,12);b.Height=60;b.Margin=new Thickness(0,0,0,10);var row=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Center};row.Children.Add(new System.Windows.Shapes.Path{Data=Geometry.Parse(geometry),Stroke=primary?Brushes.White:ink,StrokeThickness=1.8,StrokeStartLineCap=PenLineCap.Round,StrokeEndLineCap=PenLineCap.Round,Width=25,Height=25,Margin=new Thickness(0,0,text.Length==0?0:12,0)});row.Children.Add(new TextBlock{Text=text,FontSize=16,FontWeight=FontWeights.Medium,Foreground=primary?Brushes.White:ink,VerticalAlignment=VerticalAlignment.Center});b.Content=row;b.ToolTip=primary?"Installer / réparer BepInEx":"Ouvrir le dossier plugins";b.Click+=(s,e)=>Run(action);return b;}
 Button MakeButton(bool primary,double radius){var b=new Button{Cursor=Cursors.Hand,Foreground=ink,BorderThickness=new Thickness(1)};var factory=new FrameworkElementFactory(typeof(Border));factory.SetValue(Border.CornerRadiusProperty,new CornerRadius(radius));factory.SetValue(Border.BorderThicknessProperty,new Thickness(1));factory.SetValue(Border.BorderBrushProperty,new SolidColorBrush(primary?Color.FromArgb(130,170,211,255):dark?Color.FromArgb(45,255,255,255):Color.FromArgb(190,255,255,255)));factory.SetValue(Border.BackgroundProperty,new LinearGradientBrush(primary?Color.FromRgb(62,145,244):dark?Color.FromArgb(36,255,255,255):Color.FromArgb(155,255,255,255),primary?Color.FromRgb(33,98,218):dark?Color.FromArgb(12,255,255,255):Color.FromArgb(60,255,255,255),90));var presenter=new FrameworkElementFactory(typeof(ContentPresenter));presenter.SetValue(ContentPresenter.HorizontalAlignmentProperty,HorizontalAlignment.Center);presenter.SetValue(ContentPresenter.VerticalAlignmentProperty,VerticalAlignment.Center);factory.AppendChild(presenter);b.Template=new ControlTemplate(typeof(Button)){VisualTree=factory};b.MouseEnter+=(s,e)=>b.Opacity=.82;b.MouseLeave+=(s,e)=>b.Opacity=1;b.IsEnabledChanged+=(s,e)=>b.Opacity=b.IsEnabled?1:.45;buttons.Add(b);return b;}
 void Run(Action action){try{action();}catch(Exception ex){status.Text=ex.Message;status.ToolTip=ex.Message;}}
 // Windows composition blur is optional; the glass tint remains available on older systems.
 [StructLayout(LayoutKind.Sequential)]struct Accent{public int State,Flags,Color,Animation;}
 [StructLayout(LayoutKind.Sequential)]struct Composition{public int Attribute;public IntPtr Data;public int Size;}
 [DllImport("user32.dll")]static extern int SetWindowCompositionAttribute(IntPtr window,ref Composition data);
 void EnableBlur(){IntPtr memory=IntPtr.Zero;try{var accent=new Accent{State=3};memory=Marshal.AllocHGlobal(Marshal.SizeOf(accent));Marshal.StructureToPtr(accent,memory,false);var data=new Composition{Attribute=19,Data=memory,Size=Marshal.SizeOf(accent)};SetWindowCompositionAttribute(new WindowInteropHelper(this).Handle,ref data);}catch{}finally{if(memory!=IntPtr.Zero)Marshal.FreeHGlobal(memory);}}
 [STAThread]static void Main(string[] args){if(args.Contains("--self-test")){Environment.Exit(ModInstaller.Allowed("BepInEx/core/BepInEx.dll")&&!ModInstaller.Allowed("BepInEx/plugins/mod.dll")&&!ModInstaller.Allowed("BepInEx/config/mod.cfg")?0:1);return;}var app=new Application();if(args.Contains("--preview")){app.ShutdownMode=ShutdownMode.OnExplicitShutdown;foreach(bool dark in new[]{true,false}){var f=new GlassWindow(dark);f.ShowInTaskbar=false;f.WindowStartupLocation=WindowStartupLocation.Manual;f.Left=-3000;f.Top=-3000;f.Show();f.UpdateLayout();var bmp=new RenderTargetBitmap(560,365,96,96,PixelFormats.Pbgra32);bmp.Render(f);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bmp));using(var file=File.Create(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"GorillaTagModInstaller-"+(dark?"dark":"light")+".png")))encoder.Save(file);f.Close();}return;}app.Run(new GlassWindow());}
